import java.util.*;
class Team {final String name;final int points,goalDiff;Team(String n,int p,int g){name=n;points=p;goalDiff=g;}public String toString(){return name+"("+points+","+goalDiff+")";}}
class Leaderboard<T> {private final List<T> items=new ArrayList<>();private final Comparator<? super T> order;Leaderboard(Comparator<? super T> c){order=Objects.requireNonNull(c);}void add(T t){items.add(Objects.requireNonNull(t));}void addAll(List<? extends T> source){items.addAll(source);}List<T> ranking(){List<T> copy=new ArrayList<>(items);copy.sort(order);return copy;}}
public class GenericLeaderboard {public static void main(String[]x){Comparator<Team> byRank=Comparator.comparingInt((Team t)->t.points).reversed().thenComparing(Comparator.comparingInt((Team t)->t.goalDiff).reversed()).thenComparing(t->t.name);Leaderboard<Team> board=new Leaderboard<>(byRank);board.addAll(Arrays.asList(new Team("Falcons",12,8),new Team("Tigers",12,8),new Team("Lions",12,5),new Team("Wolves",9,10)));System.out.println("Ranking: "+board.ranking());Comparator<Team> faulty=(a,b)->a.points-b.points;System.out.println("Correct comparator ties by goal difference and name; subtraction comparator may overflow and omits tie-breakers.");}}
